from moler.device.proxy_pc3 import ProxyPc3


class NokiaProxyPc3(ProxyPc3):
    """ProxyPc with specific Nokia commands and events."""

    def _get_packages_for_state(self, state, observer):
        """
        Get available packages contain cmds and events for each state.

        :param state: device state.
        :param observer: observer type, available: cmd, events
        :return: available cmds or events for specific device state.
        """
        if state == ProxyPc3.unix_local or state == ProxyPc3.unix_local_root or state == ProxyPc3.proxy_pc:
            available = {
                NokiaProxyPc3.cmds: ["moler.cmd.unix", "ta_moler.cmd.shared.nokiaunix"],
                NokiaProxyPc3.events: ["moler.events.shared", "moler.events.unix"],
            }
            return available[observer]
        return []
